      .sort((a, b) => {
        if (sortMode === "name") return a.label.localeCompare(b.label);
        if (sortMode === "newest") return b.newest - a.newest;
        return Math.abs(b.delta) - Math.abs(a.delta);
      })
      .map((m) => ({
        ...m,
        fill:
          m.confidence === "carried"
            ? COLORS.carried
            : m.betterWhen === "up"
              ? m.delta >= 0
                ? COLORS.newest
                : COLORS.up
              : m.betterWhen === "down"
                ? m.delta <= 0
