        if (sortMode === "newest") return b.newest - a.newest;
        return Math.abs(b.delta) - Math.abs(a.delta);
      })
      .map((r) => ({
        ...r,
        signed: r.delta,
        fill:
          r.confidence === "carried"
            ? COLORS.carried
            : r.delta > 0
              ? r.lane === "donors"
                ? COLORS.newest
                : COLORS.up
              : r.delta < 0
                ? COLORS.down
                : COLORS.carried,
