            {fmtDelta(HEADLINE.unhcrBudgetDeltaPct, "pct", 0)}
          </strong>{" "}
          while{" "}
          <strong className="text-amber-300">
            {fmtM(HEADLINE.atRiskCutsM)}
          </strong>{" "}
          remain flagged at risk from funding cuts.
        </p>
        <div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4">
          {[
