                +16pp heal ??? not an official FTS allocation of the coverage
                delta.
              </p>
            </ChartCard>
          </div>

          <ChartCard
            title="Q3 ??? August vintage meters"
            subtitle="Donor shares are the new print; cash coverage and people meters are flat/carried"
          >
            <div className="h-[360px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart
                  layout="vertical"
                  data={meters}
                  margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="label"
                    width={140}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip content={<MeterTooltip />} />
                  <Bar
                    dataKey="prior"
                    barSize={6}
                    fill={COLORS.prior}
                    radius={[2, 2, 2, 2]}
                    name="Q3"
                  />
                  <Bar
                    dataKey="newest"
                    barSize={10}
                    radius={[3, 3, 3, 3]}
                    name="Aug"
                  >
                    {meters.map((m) => (
                      <Cell key={m.id} fill={m.fill} />
                    ))}
                  </Bar>
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </>
      )}

      {view === "asymmetry" && (
        <>
          <ChartCard
            title="Hosts still carry people ??? donors concentrate cash"
            subtitle="LMIC 68% hosting vs FTS Top-3 ~45% of tracked funding"
          >
            <div className="h-[340px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  layout="vertical"
                  data={asymmetryBars}
                  margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={160}
                    tick={{ fontSize: 10 }}
                  />
                  <Tooltip
                    formatter={(v, _n, item) => {
                      const row = item?.payload as (typeof asymmetryBars)[0];
                      if (!row) return [v, ""];
                      const display =
                        row.unit === "bn"
                          ? fmtBn(Number(v), 2)
                          : fmtPct(Number(v), row.value % 1 === 0 ? 0 : 1);
                      return [display, row.side];
                    }}
                  />
                  <Bar dataKey="value" radius={[0, 4, 4, 0]}>
                    {asymmetryBars.map((r) => (
                      <Cell key={r.meter} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <div className="grid gap-6 lg:grid-cols-2">
            <ChartCard
              title="Who-bears-it scoreboard (??)"
              subtitle="Donor shares are the August move; host and agency meters mostly flat"
            >
              <div className="h-[320px] w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart
                    layout="vertical"
                    data={burdens}
                    margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis type="number" tick={{ fontSize: 11 }} />
                    <YAxis
                      type="category"
                      dataKey="short"
                      width={88}
                      tick={{ fontSize: 11 }}
                    />
                    <ReferenceLine x={0} stroke="#94a3b8" />
                    <Tooltip content={<BurdenTooltip />} />
                    <Bar dataKey="signed" radius={[0, 4, 4, 0]}>
                      {burdens.map((b) => (
                        <Cell key={b.id} fill={b.fill} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>

            <ChartCard
              title="People stock vs coverage (+ Top-1 donor)"
              subtitle="Displacement carried; coverage healed in Q3; Top-1 printed in August"
            >
              <div className="h-[320px] w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <ComposedChart
                    data={STOCK_VS_CASH}
                    margin={{ top: 8, right: 16, left: 0, bottom: 8 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis dataKey="vintage" tick={{ fontSize: 9 }} />
                    <YAxis
                      yAxisId="left"
                      tick={{ fontSize: 11 }}
                      tickFormatter={(v) => `${v}M`}
                    />
                    <YAxis
                      yAxisId="right"
                      orientation="right"
                      tick={{ fontSize: 11 }}
                      tickFormatter={(v) => `${v}%`}
                      domain={[0, 50]}
                    />
                    <Tooltip />
                    <Bar
                      yAxisId="left"
                      dataKey="displacedM"
                      fill={COLORS.prior}
                      name="Displaced (M)"
                      radius={[4, 4, 0, 0]}
                    />
                    <Line
                      yAxisId="right"
                      type="monotone"
                      dataKey="coveragePct"
                      stroke={COLORS.newest}
                      strokeWidth={3}
                      name="GHO coverage %"
                      dot={{ r: 4 }}
                    />
                    <Line
                      yAxisId="right"
                      type="monotone"
                      dataKey="top1DonorPct"
                      stroke={COLORS.violet}
                      strokeWidth={3}
                      strokeDasharray="4 4"
                      name="FTS Top-1 %"
                      connectNulls={false}
                      dot={{ r: 5 }}
                    />
                  </ComposedChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>
          </div>

          <div className="grid gap-6 lg:grid-cols-2">
            <ChartCard
              title="GHO cash path (context from Q3)"
              subtitle="Requirements, funded, gap ??? coverage heal already booked"
            >
              <div className="h-[260px] w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <ComposedChart
                    data={GHO_CASH_PATH}
                    margin={{ top: 8, right: 16, left: 0, bottom: 8 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis dataKey="label" tick={{ fontSize: 12 }} />
                    <YAxis
                      tick={{ fontSize: 11 }}
                      tickFormatter={(v) => `$${v}B`}
                    />
                    <Tooltip formatter={(v) => fmtBn(Number(v), 2)} />
                    <Bar
                      dataKey="reqBn"
                      fill={COLORS.prior}
                      name="Requirements"
                      radius={[4, 4, 0, 0]}
                    />
                    <Bar
                      dataKey="fundedBn"
                      fill={COLORS.newest}
                      name="Funded"
                      radius={[4, 4, 0, 0]}
                    />
                    <Line
                      type="monotone"
                      dataKey="gapBn"
                      stroke={COLORS.up}
                      strokeWidth={3}
                      name="Unfunded gap"
                      dot={{ r: 5 }}
                    />
